import mongoose, { Schema } from "mongoose";
import { getNextReportNumber } from "../utils/activityReportHelpers.js";
// Sub-schema for attendance records
const attendanceRecordSchema = new Schema({
    employeeId: { type: Schema.Types.ObjectId, ref: "User", required: true },
    /*
      QUÉ TIPO DE NOVEDAD ES, por id.

      Antes el tipo viajaba sólo como TEXTO en `absenceReason` —el nombre del tipo, copiado—, y eso
      no alcanza para colgarle consecuencias: renombrar un tipo en el ABM desconectaba de golpe
      todos los partes viejos, y las horas extra directamente no dejaban motivo, así que no había
      forma de identificarlas. El motor de efectos necesita saber de qué tipo es cada renglón para
      saber qué cuenta mover.

      `absenceReason` se conserva tal cual: es lo que muestran las pantallas hoy y lo que tienen
      cargado los 7.920 renglones que ya existen.
    */
    typeId: { type: Schema.Types.ObjectId, ref: "RequestConfig" },
    status: {
        type: String,
        enum: ["present", "absent", "late", "vacation", "sick", "unpaid", "compensatory"],
        required: true,
    },
    absenceReason: { type: String }, // e.g., "Enfermedad", "Falta injustificada"
    replacementId: { type: Schema.Types.ObjectId, ref: "User" },
    overtimeHours: { type: Number, default: 0 },
    replacementOvertimeHours: { type: Number, default: 0 },
    overtimeHours50: { type: Number, default: 0 },
    overtimeHours100: { type: Number, default: 0 },
    replacementOvertimeHours50: { type: Number, default: 0 },
    replacementOvertimeHours100: { type: Number, default: 0 },
    inTime: { type: String }, // Real Entry Time
    outTime: { type: String }, // Real Exit Time
    replacementInTime: { type: String }, // Real Entry Time for Replacement
    replacementOutTime: { type: String }, // Real Exit Time for Replacement
    scheduleInTime: { type: String }, // Expected Entry
    scheduleOutTime: { type: String }, // Expected Exit
    notes: { type: String },
}, { _id: true });
const requestSchema = new Schema({
    tenantId: { type: Schema.Types.ObjectId, ref: "Tenant", required: true },
    userId: { type: Schema.Types.ObjectId, ref: "User", required: true },
    reportNumber: { type: String, trim: true, uppercase: true }, // Not required initially, generated by hook
    /*
      CUÁNTAS VECES SE EDITÓ ESTE PARTE.

      Los movimientos del banco de días guardan con qué versión se generaron, y eso es lo que hace
      que reprocesar un parte no duplique días: si ya hay movimientos de esta versión, no se emiten
      de nuevo. Sin un número que suba, «la misma novedad» y «la novedad corregida» son
      indistinguibles.

      Sube en el PUT (ver `routes/activityReports.ts`). Los partes que ya existían arrancan en 1.
    */
    version: { type: Number, default: 1 },
    date: { type: String, required: true }, // Format YYYY-MM-DD
    projectId: { type: Schema.Types.ObjectId, ref: "Project" },
    areaId: { type: Schema.Types.ObjectId, ref: "Area" }, // Optional linkage to Area
    shiftId: { type: Schema.Types.ObjectId, ref: "Shift" }, // Optional linkage to Shift
    hasActivity: { type: Boolean, default: true },
    comments: { type: String },
    attendance: [attendanceRecordSchema],
    submittedAt: { type: Date, default: Date.now },
}, { timestamps: true, collection: "requests" });
// Indexes
requestSchema.index({ tenantId: 1, userId: 1, date: -1 });
requestSchema.index({ tenantId: 1, reportNumber: 1 }, { unique: true, sparse: true });
// Pre-validate hook for reportNumber
requestSchema.pre("validate", async function (next) {
    if (!this.isNew || this.reportNumber) {
        return next();
    }
    const maxRetries = 5;
    let attempt = 0;
    while (attempt < maxRetries) {
        try {
            const Tenant = mongoose.models.Tenant || mongoose.model("Tenant");
            const tenant = await Tenant.findById(this.tenantId);
            if (!tenant) {
                console.warn("Tenant not found for report number generation");
                this.reportNumber = `UNK-REG-${Date.now()}`; // Fallback
                return next();
            }
            const prefix = tenant.slug ? tenant.slug.toUpperCase().slice(0, 3) : "UNK";
            this.reportNumber = await getNextReportNumber(this.tenantId, prefix);
            return next();
        }
        catch (error) {
            if (error.code === 11000 && attempt < maxRetries - 1) {
                attempt++;
                await new Promise((resolve) => setTimeout(resolve, Math.random() * 100)); // Jitter
                continue;
            }
            return next(error); // Pass error if not duplicate key or retries exhausted
        }
    }
    return next(new Error("Failed to generate unique report number after multiple attempts"));
});
export const Request = mongoose.model("Request", requestSchema);
